-- 48 — MANG 34 CẢI TRANG TỪ SOURCE HUNR (sinh bởi tools/port_item_from_hunr.py)
-- =====================================================================
-- Vật phẩm 2080..2113, part 2238..2339, avatar tự dựng từ mảnh đầu.
--
-- * Ảnh đã chép sẵn vào data/icon/x1..x4, icon trùng số với mình thì đã đánh số lại.
-- * HUNR không có bảng head_avatar nên avatar được ghép từ mảnh đầu rồi phóng to.
-- * Chưa có chỉ số: phát qua shop / giftcode / cpanel "Buff đồ" rồi thêm option.
--
-- Chạy cùng jar có DataGame.vsItem và vsData đã tăng. Khởi động lại server.
-- Chạy lại nhiều lần vẫn an toàn (tự xoá đúng dải của mình trước khi thêm).
-- TRƯỚC KHI CHẠY: hai câu dưới phải ra 2079 và 2237; khác thì DỪNG, báo lại.
-- =====================================================================
SELECT MAX(`id`) AS item_max FROM `item_template`;
SELECT MAX(`id`) AS part_max FROM `part`;

DELETE FROM `item_template` WHERE `id` BETWEEN 2080 AND 2113;
DELETE FROM `part`          WHERE `id` BETWEEN 2238 AND 2339;
DELETE FROM `head_avatar`   WHERE `head_id` BETWEEN 2238 AND 2339;




SELECT `id`, `NAME`, `icon_id`, `head`, `body`, `leg` FROM `item_template` WHERE `id` BETWEEN 2080 AND 2113;
